//! Real WebView2 gate on a disposable window, with no Host or provider runtime.
use std::sync::{Arc,Mutex,atomic::{AtomicUsize,Ordering}};
use tauri::Manager;
static INVOKED:AtomicUsize=AtomicUsize::new(0);
#[tauri::command]fn presentation_probe()->String{INVOKED.fetch_add(1,Ordering::SeqCst);"parent-only".into()}
#[test]
#[ignore="explicit disposable WebView2 isolation check; no accounts or Host"]
fn native_published_frame_reads_presentation_but_cannot_reach_parent_or_ipc(){
 INVOKED.store(0,Ordering::SeqCst);let proof=Arc::new(Mutex::new(None::<serde_json::Value>));let result=proof.clone();
 let evidence=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("runtime/published-board-native");std::fs::create_dir_all(&evidence).unwrap();
 let profile=tempfile::tempdir_in(&evidence).unwrap();let profile_path=profile.path().to_owned();
 let child=r#"<!doctype html><html><body><h1>Published result</h1><script>(async()=>{let parentDOM=false,nativeIPC=false;try{parentDOM=!!parent.document.body}catch{}try{nativeIPC=(await Promise.race([window.__TAURI_INTERNALS__.invoke('presentation_probe'),new Promise(r=>setTimeout(()=>r('timeout'),2000))]))==='parent-only'}catch{}parent.postMessage({kind:'state',channel:'native-fixture-channel',scrollY:0,hash:'#proof',parentDOM,nativeIPC,readable:document.querySelector('h1').textContent==='Published result'},'*')})()</script></body></html>"#;
 let child_json=serde_json::to_string(child).unwrap();
 let script=format!(r#"let own=null,child=null;const finish=()=>{{if(own!==null&&child)fetch('/proof?value='+encodeURIComponent(JSON.stringify({{parentIPC:own,...child}})))}};window.__TAURI_INTERNALS__.invoke('presentation_probe').then(v=>{{own=v==='parent-only';finish()}}).catch(()=>{{own=false;finish()}});addEventListener('message',e=>{{if(e.source===document.querySelector('iframe').contentWindow&&e.origin==='null'&&e.data?.kind==='state'){{child=e.data;finish()}}}});document.querySelector('iframe').onload=()=>{{if(!window.sent){{window.sent=true;document.querySelector('iframe').contentWindow.postMessage({{kind:'document',channel:'native-fixture-channel',html:{child_json}}},'*')}}}};"#);
 let mut context=tauri::generate_context!();context.config_mut().app.windows.clear();context.config_mut().build.dev_url=None;context.config_mut().identifier="cc.agbrio.published-board-check".into();
 let app=tauri::Builder::default().any_thread().invoke_handler(tauri::generate_handler![presentation_probe])
 .register_uri_scheme_protocol("tauri",move|ctx,req|{let u=url::Url::parse(&req.uri().to_string()).unwrap();let (mime,body)=match u.path(){"/parent"=>("text/html","<html><body><iframe sandbox='allow-scripts' src='http://published-board.localhost/view'></iframe><script src='/parent.js'></script></body></html>".to_string()),"/parent.js"=>("text/javascript",script.clone()),"/proof"=>{let value=u.query_pairs().find(|(k,_)|k=="value").unwrap().1.into_owned();*result.lock().unwrap()=Some(serde_json::from_str(&value).unwrap());ctx.app_handle().exit(0);("text/plain","ok".into())},_=>("text/plain","not found".into())};tauri::http::Response::builder().header("Content-Type",mime).header("Content-Security-Policy","default-src 'self'; script-src 'self'; frame-src http://published-board.localhost").body(body.into_bytes()).unwrap()})
 .register_uri_scheme_protocol("published-board",move|_,_|tauri::http::Response::builder().header("Content-Type","text/html; charset=utf-8").header("Content-Security-Policy",super::HOST_CSP).body(super::FRAME_LOADER.as_bytes().to_vec()).unwrap())
 .setup(move|app|{tauri::WebviewWindowBuilder::new(app,"main",tauri::WebviewUrl::External(url::Url::parse("http://tauri.localhost/parent").unwrap())).title("Agbrio presentation isolation check").data_directory(profile_path).focused(false).inner_size(800.,600.).build()?;let handle=app.handle().clone();std::thread::spawn(move||{std::thread::sleep(std::time::Duration::from_secs(20));handle.exit(1);});Ok(())}).build(context).unwrap();
 let code=app.run_return(|_,_|{});assert_eq!(code,0);let guard=proof.lock().unwrap();let p=guard.as_ref().expect("bounded native proof");assert_eq!(p["parentIPC"],true);assert_eq!(p["readable"],true);assert_eq!(p["parentDOM"],false);assert_eq!(p["nativeIPC"],false);assert_eq!(INVOKED.load(Ordering::SeqCst),1);println!("NATIVE_PUBLISHED_BOARD_PASS parentIPC=true readable=true parentDOM=false nativeIPC=false providers=0");
}
